<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
const props=defineProps<{projects:any[];selectedId:number|null;permissions:string[];busy:boolean}>();
const emit=defineEmits(['select','preview','edit','delete','assign','tasks','discussion','submissions','status','approval','removeMember']);
const menu=ref<number|null>(null);
const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);
const leads=(project:any)=>(project.users||[]).filter((user:any)=>user.roles?.some((role:any)=>['project_manager','team_leader'].includes(role.role_key)));
function action(type:string,project:any){menu.value=null;emit(type as any,project);}
function status(project:any,event:Event,type:'status'|'approval'){menu.value=null;emit(type,project,(event.target as HTMLSelectElement).value);}
function outside(event:PointerEvent){if(!(event.target as Element)?.closest('.pms-project-card-menu,.pms-shared-select-menu'))menu.value=null;}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&menu.value!==null){const id=menu.value;menu.value=null;document.getElementById('project-actions-'+id)?.focus();}}
function description(value:string){return new DOMParser().parseFromString(value||'','text/html').body.textContent?.trim()||'Select this project to explore its departments and sprint boards.';}
function date(value:string){return value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'';}
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);});
onUnmounted(()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);});
</script>
<template>
 <div class="pms-project-grid">
  <article v-for="project in projects" :key="project.id" class="pms-project-card" :class="{selected:selectedId===project.id}">
   <header class="pms-project-card-top"><img v-if="project.image" :src="project.image" alt="" class="pms-project-card-logo"><span v-else class="pms-project-card-logo">{{project.name.charAt(0).toUpperCase()}}</span><span class="pms-project-card-status" :class="'status-'+project.status">{{project.status?.replaceAll('_',' ')}}</span><div class="pms-project-card-menu"><button :id="'project-actions-'+project.id" type="button" class="pms-project-card-more" :aria-label="'Actions for '+project.name" :aria-expanded="menu===project.id" :aria-controls="'project-menu-'+project.id" :disabled="busy" @click="menu=menu===project.id?null:project.id"><i class="ti ti-dots" aria-hidden="true"></i></button><div v-if="menu===project.id" :id="'project-menu-'+project.id" class="pms-project-card-options" :aria-label="'Project actions for '+project.name"><button @click="action('preview',project)"><i class="ti ti-eye" aria-hidden="true"></i>Preview details</button><button @click="action('tasks',project)"><i class="ti ti-list-check" aria-hidden="true"></i>View tasks</button><button v-if="can('project-edit')" @click="action('edit',project)"><i class="ti ti-edit" aria-hidden="true"></i>Edit project</button><button v-if="can('project-assign')" @click="action('assign',project)"><i class="ti ti-user-plus" aria-hidden="true"></i>Assign members</button><button @click="action('discussion',project)"><i class="ti ti-message" aria-hidden="true"></i>Comments</button><button @click="action('submissions',project)"><i class="ti ti-send" aria-hidden="true"></i>Submissions</button><template v-if="can('project-edit')"><label>Status<select :value="project.status" :aria-label="'Status for '+project.name" @change="status(project,$event,'status')"><option v-for="value in ['pending','progress','completed','delivered','cancelled']" :key="value" :value="value">{{value.charAt(0).toUpperCase()+value.slice(1)}}</option></select></label><label>Approval<select :value="project.approval" :aria-label="'Approval for '+project.name" @change="status(project,$event,'approval')"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></label></template><button v-if="can('project-trash')" class="delete" @click="action('delete',project)"><i class="ti ti-trash" aria-hidden="true"></i>Delete project</button></div></div></header>
   <button type="button" class="pms-project-card-open" :aria-label="'Show departments for '+project.name" :aria-pressed="selectedId===project.id" aria-controls="pms-project-department-panel" @click="emit('select',project.id)"><span class="pms-project-card-title">{{project.name}}</span><span class="pms-project-card-description">{{description(project.description)}}</span></button>
   <div class="pms-project-card-facts"><button :aria-label="'Open tasks for '+project.name" @click="emit('tasks',project)"><i class="ti ti-list-check" aria-hidden="true"></i>{{project.tasks_count||0}} tasks</button><span class="pms-project-card-approval" :class="'approval-'+project.approval"><i :class="['ti',project.approval==='approved'?'ti-circle-check':'ti-hourglass']" aria-hidden="true"></i>{{project.approval||'pending'}}</span><span v-if="project.end_date" :class="{'text-danger':project.is_overdue}"><i class="ti ti-calendar" aria-hidden="true"></i>{{date(project.end_date)}}</span></div>
   <footer class="pms-project-card-footer"><div class="pms-project-leads"><button v-for="user in leads(project)" :key="user.id" :title="can('project-assign')?'Remove '+user.name:user.name" :aria-label="'Project member '+user.name" :disabled="!can('project-assign')||busy" @click="emit('removeMember',project,user)"><img v-if="user.profile_img" :src="user.profile_img" :alt="user.name"><span v-else>{{user.name.charAt(0)}}</span></button><button v-if="can('project-assign')" :aria-label="'Assign members to '+project.name" :disabled="busy" @click="emit('assign',project)">+</button></div><button class="pms-project-card-departments" @click="emit('select',project.id)">{{selectedId===project.id?'Departments below':'View departments'}}<i class="ti" :class="selectedId===project.id?'ti-chevron-down':'ti-arrow-right'" aria-hidden="true"></i></button></footer>
  </article>
 </div>
</template>
<style scoped>
.pms-project-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(265px,1fr));gap:18px;padding:0 0 8px}.pms-project-card{position:relative;display:flex;flex-direction:column;min-width:0;background:var(--pms-surface);border:1px solid var(--pms-border);border-radius:12px;padding:20px;transition:border-color .15s,box-shadow .15s}.pms-project-card:hover{border-color:var(--pms-primary)}.pms-project-card.selected{border-color:var(--pms-primary);box-shadow:0 0 0 1px var(--pms-primary)}.pms-project-card-top{display:flex;align-items:center;gap:12px;margin-bottom:18px}.pms-project-card-logo{width:42px;height:42px;border-radius:10px;display:grid;place-items:center;object-fit:cover;background:var(--pms-primary-soft);color:var(--pms-primary);font-size:18px;font-weight:600;flex-shrink:0}.pms-project-card-status{font-size:10px;text-transform:capitalize;padding:4px 8px;border-radius:5px;background:var(--pms-primary-soft);color:var(--pms-primary)}.pms-project-card-status.status-completed,.pms-project-card-status.status-delivered{background:#28c76f19;color:#28a862}.pms-project-card-status.status-cancelled{background:#ea545519;color:#ea5455}.pms-project-card-menu{margin-left:auto;position:relative}.pms-project-card-more{width:30px;height:30px;border:0;border-radius:6px;background:transparent;color:var(--pms-muted);display:grid;place-items:center;cursor:pointer}.pms-project-card-more:hover{background:var(--pms-primary-soft);color:var(--pms-primary)}.pms-project-card-more .ti{font-size:20px}.pms-project-card-options{position:absolute;right:0;top:calc(100% + 6px);z-index:35;width:210px;max-height:min(520px,70vh);overflow-y:auto;padding:7px;background:var(--pms-surface);border:1px solid var(--pms-border);border-radius:9px;box-shadow:0 12px 30px #0003}.pms-project-card-options>button{display:flex;gap:9px;align-items:center;background:none;color:var(--pms-text);border:0;border-radius:5px;width:100%;padding:9px 10px;text-align:left;font:inherit;font-size:12px;cursor:pointer}.pms-project-card-options>button:hover{background:var(--pms-primary-soft)}.pms-project-card-options>button.delete{color:#ea5455}.pms-project-card-options label{display:grid;gap:7px;font-size:11px;color:var(--pms-muted);padding:8px 10px;border-top:1px solid var(--pms-border)}.pms-project-card-options select{width:100%;font:inherit;border:1px solid var(--pms-border);border-radius:5px;padding:7px;background:var(--pms-surface);color:var(--pms-text)}.pms-project-card-open{display:grid;gap:10px;text-align:left;background:none;color:var(--pms-text);border:0;cursor:pointer;padding:0;width:100%;min-width:0}.pms-project-card-title{font-size:16px;line-height:1.4;font-weight:600;overflow-wrap:anywhere}.pms-project-card-description{font-size:12px;line-height:1.7;color:var(--pms-muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:40px}.pms-project-card-facts{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:20px 0;font-size:11px;color:var(--pms-muted)}.pms-project-card-facts>span,.pms-project-card-facts>button{display:flex;align-items:center;gap:5px}.pms-project-card-facts>button{border:0;padding:0;background:none;color:inherit;font:inherit;cursor:pointer}.pms-project-card-approval{text-transform:capitalize}.pms-project-card-approval.approval-approved{color:#28a862}.pms-project-card-approval.approval-rejected{color:#ea5455}.pms-project-card-footer{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin:auto 0 0;padding:16px 0 0;text-align:left;border-top:1px solid var(--pms-border)}.pms-project-card-departments{display:flex;gap:7px;align-items:center;background:none;border:0;color:var(--pms-primary);font:inherit;font-size:12px;cursor:pointer;padding:0;text-align:right}.pms-project-card:has(.pms-project-card-options){z-index:2}.pms-project-card button:focus-visible{outline:2px solid var(--pms-primary);outline-offset:4px}@media(max-width:550px){.pms-project-grid{grid-template-columns:1fr;gap:14px}.pms-project-card{padding:18px}}@media(prefers-reduced-motion:reduce){.pms-project-card{transition:none}}
</style>
